        nome_unidade: 'Oral Concept - Tirol',
        nome_empresa: 'Oral Concept',
        endereco: 'Av. Campos Sales, 901 – Sala 912, Tirol – Natal/RN',
        timezone: TIMEZONE,
        regras_horario: {
            1: [{ ini: {h:8,m:0}, fim: {h:12,m:0} }, { ini: {h:14,m:0}, fim: {h:18,m:0} }],
            2: null,
