        nome_unidade: 'Oral Conceito - Nova Esperança',
        nome_empresa: 'Oral Conceito',
        endereco: 'Rua Rosa Fernandes da Silva, 355 – Nova Esperança – Parnamirim/RN',
        timezone: TIMEZONE,
        regras_horario: {
            1: [{ ini: {h:8,m:0}, fim: {h:12,m:0} }, { ini: {h:13,m:0}, fim: {h:17,m:0} }],
            2: null,
            3: [{ ini: {h:8,m:0}, fim: {h:12,m:0} }, { ini: {h:13,m:0}, fim: {h:17,m:0} }],
            4: [{ ini: {h:8,m:0}, fim: {h:12,m:0} }, { ini: {h:13,m:0}, fim: {h:17,m:0} }],
            5: [{ ini: {h:8,m:0}, fim: {h:12,m:0} }, { ini: {h:13,m:0}, fim: {h:17,m:0} }],
            6: [{ ini: {h:8,m:0}, fim: {h:12,m:0} }],
            7: null
        },
        duracao_servico: 30,
        capacidade_simultanea: 1,
        trava_agendamento: 5,
        trava_remarcacao: 2
    }
};

const unidadeKey = body.unidade || 'oral_concept_tirol';
const config_agenda = CONFIGS[unidadeKey] || CONFIGS['oral_concept_tirol'];

let dataFinal = '';
let horaFinal = '';
let dataAntigaBusca = null;

const dataRaw = body.data_iso || body.data_inicio || body.data_agendada;
if (dataRaw) {
    let dt = DateTime.fromISO(dataRaw, { zone: TIMEZONE });
    if (!dt.isValid) dt = DateTime.fromFormat(dataRaw, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
    if (dt.isValid) {
        dataFinal = dt.toFormat('dd/MM/yyyy');
        horaFinal = dt.toFormat('HH:mm');
    }
}

if (body.data_antiga) {
    let dtAntiga = DateTime.fromISO(body.data_antiga, { zone: TIMEZONE });
    if (!dtAntiga.isValid) dtAntiga = DateTime.fromFormat(body.data_antiga, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
    if (dtAntiga.isValid) dataAntigaBusca = dtAntiga.toISO();
}

return {
  json: {
    ...body,
    data_agendada: dataFinal,
    horario_agendado: horaFinal,
    data_antiga_iso: dataAntigaBusca,
    telefone_limpo: telefoneLimpo,
    nome_paciente: nomePaciente,
    unidade_selecionada: unidadeKey,
    config_agenda: config_agenda,
    acao_fluxo: body.action
  }
};

const itemConfig = $('Configuracao Unidades').first().json;
const configAgenda = itemConfig.config_agenda || {};

const TIMEZONE = configAgenda.timezone || 'America/Sao_Paulo';
const DURACAO_MINUTOS = configAgenda.duracao_servico || 15;
const CAPACIDADE_MAXIMA = configAgenda.capacidade_simultanea || 2;
const MIN_GAP_MINUTES = 60;

const feriados = configAgenda.feriados || ["2026-01-01", "2026-04-21", "2026-05-01"];

const eventosOcupados = $input.all().map(i => i.json);
const agora = DateTime.now().setZone(TIMEZONE);
const inicioSeguro = agora.plus({ hours: 2 });

const isFeriado = (data) => feriados.includes(data.toFormat('yyyy-MM-dd'));

function isSlotAvailable(slotStart) {
    if (isFeriado(slotStart)) return false;
    let ocupados = 0;
    const slotEnd = slotStart.plus({ minutes: DURACAO_MINUTOS });
    for (const evento of eventosOcupados) {
        if (!evento || !evento.status || evento.status === 'cancelled') continue;
        let iniEvt, fimEvt;
        if (evento.start?.dateTime) {
            iniEvt = DateTime.fromISO(evento.start.dateTime).setZone(TIMEZONE);
        } else if (evento.start?.date) {
            iniEvt = DateTime.fromISO(evento.start.date).setZone(TIMEZONE).startOf('day');
        } else { continue; }
        if (evento.end?.dateTime) {
            fimEvt = DateTime.fromISO(evento.end.dateTime).setZone(TIMEZONE);
        } else if (evento.end?.date) {
            fimEvt = DateTime.fromISO(evento.end.date).setZone(TIMEZONE).endOf('day');
        } else { continue; }
        if (slotStart < fimEvt && slotEnd > iniEvt) ocupados++;
    }
    return ocupados < CAPACIDADE_MAXIMA;
}

const getMin = (cfg) => cfg.h * 60 + cfg.m;

// Regras como array de períodos — regraValida se for array não-vazio
const regraValida = (regra) => Array.isArray(regra) && regra.length > 0;

const dataEntrada = itemConfig.data_inicio || itemConfig.data_iso;
let horarioSolicitado = dataEntrada ? DateTime.fromISO(dataEntrada, { zone: TIMEZONE }) : agora;

const solicitouHorarioEspecifico = horarioSolicitado.isValid && (horarioSolicitado.hour !== 0 || horarioSolicitado.minute !== 0);

let solicitadoDisponivel = false;
if (solicitouHorarioEspecifico && horarioSolicitado >= inicioSeguro && !isFeriado(horarioSolicitado)) {
    const diaSem = horarioSolicitado.weekday;
    const regraDia = configAgenda.regras_horario ? configAgenda.regras_horario[diaSem] : null;
    if (regraValida(regraDia)) {
        const minSol = horarioSolicitado.hour * 60 + horarioSolicitado.minute;
        const minFimSol = minSol + DURACAO_MINUTOS;
        for (const periodo of regraDia) {
            if (minSol >= getMin(periodo.ini) && minFimSol <= getMin(periodo.fim) && isSlotAvailable(horarioSolicitado)) {
                solicitadoDisponivel = true;
                break;
            }
        }
    }
}

function buscarSugestoes(diaInicial, periodoPreferencia) {
    const sugestoes = [];
    let cursorDia = diaInicial;
    if (cursorDia < agora.startOf('day')) cursorDia = agora.startOf('day');
    let diasVerificados = 0;
    const MAX_DIAS_BUSCA = 7;
    const MAX_OPCOES = 3;

    while (sugestoes.length < MAX_OPCOES && diasVerificados < MAX_DIAS_BUSCA) {
        const regraDia = configAgenda.regras_horario ? configAgenda.regras_horario[cursorDia.weekday] : null;

        if (regraValida(regraDia) && !isFeriado(cursorDia)) {
            for (const periodo_dia of regraDia) {
                if (sugestoes.length >= MAX_OPCOES) break;
                // Pula período incompatível com preferência
                if (periodoPreferencia === 'manha' && periodo_dia.ini.h >= 12) continue;
                if (periodoPreferencia === 'tarde' && periodo_dia.fim.h <= 12) continue;

                let loopTime = cursorDia.set({ hour: periodo_dia.ini.h, minute: periodo_dia.ini.m });
                if (periodoPreferencia === 'tarde' && loopTime.hour < 12) {
                    loopTime = loopTime.set({ hour: 12, minute: 0 });
                }
                const fimTurno = cursorDia.set({ hour: periodo_dia.fim.h, minute: periodo_dia.fim.m });

                while (loopTime.plus({ minutes: DURACAO_MINUTOS }) <= fimTurno) {
                    if (sugestoes.length >= MAX_OPCOES) break;
                    if (periodoPreferencia === 'manha' && loopTime.hour >= 12) break;

                    if (loopTime >= inicioSeguro && isSlotAvailable(loopTime)) {
                        sugestoes.push(loopTime);
                        loopTime = loopTime.plus({ minutes: MIN_GAP_MINUTES });
                    } else {
                        loopTime = loopTime.plus({ minutes: DURACAO_MINUTOS });
                    }
                }
            }
        }
        cursorDia = cursorDia.plus({ days: 1 });
        diasVerificados++;
    }
    return sugestoes;
}

let respostaFinal = '';
let sugestoesISO = [];

if (solicitadoDisponivel) {
    const fmt = horarioSolicitado.setLocale('pt-BR').toFormat('dd/MM (ccc)');
    const hora = horarioSolicitado.toFormat('HH:mm');
    respostaFinal = `✅ O horário solicitado está disponível!\n\n🗓️ *${fmt}* às *${hora}*\n🏥 Unidade: ${configAgenda.nome_unidade}\n\nDeseja confirmar o agendamento?`;
    sugestoesISO = [horarioSolicitado.toISO()];
} else {
    const diaInicial = solicitouHorarioEspecifico ? horarioSolicitado.startOf('day') : (horarioSolicitado || agora).startOf('day');
    const periodoPreferencia = itemConfig.periodo_preferencia;
    const sugestoes = buscarSugestoes(diaInicial, periodoPreferencia);

    if (sugestoes.length > 0) {
        const linhas = sugestoes
            .map(s => `🗓️ *${s.setLocale('pt-BR').toFormat('dd/MM (ccc)')}* às *${s.toFormat('HH:mm')}*`)
            .join('\n');

        if (solicitouHorarioEspecifico) {
            respostaFinal = `O horário de ${horarioSolicitado.toFormat('HH:mm')} não está disponível. Mas encontrei estas opções na ${configAgenda.nome_unidade}:\n\n${linhas}\n\nQual desses fica melhor para você?`;
        } else {
            const txtPeriodo = periodoPreferencia ? ` para o período da ${periodoPreferencia}` : '';
            respostaFinal = `Encontrei estes horários disponíveis na ${configAgenda.nome_unidade}${txtPeriodo}:\n\n${linhas}\n\nAlgum desses funciona para você?`;
        }
    } else {
        respostaFinal = `Não encontrei horários disponíveis nos próximos dias na ${configAgenda.nome_unidade}. Gostaria de tentar outra data?`;
    }
    sugestoesISO = sugestoes.map(s => s.toISO());
}

return {
    json: {
        resultado: respostaFinal,
        sugestoes_iso: sugestoesISO,
        horario_solicitado_disponivel: solicitadoDisponivel
    }
};

const itemConfig = $('Configuracao Unidades').first();
const dadosOriginais = itemConfig.json;
const configAgenda = dadosOriginais.config_agenda;

const TIMEZONE = configAgenda.timezone || 'America/Sao_Paulo';
const DURACAO_MINUTOS = configAgenda.duracao_servico || 15;
const CAPACIDADE_MAXIMA = configAgenda.capacidade_simultanea || 2;

const eventosOcupados = $input.all().map(i => i.json);

const dataStr = dadosOriginais.data_agendada;
const horaStr = dadosOriginais.horario_agendado;
const dataAlvo = DateTime.fromFormat(`${dataStr} ${horaStr}`, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });

let validacao = { aprovado: false, motivo: '' };
const getMin = (cfg) => cfg.h * 60 + cfg.m;

if (!dataAlvo.isValid) {
    validacao.motivo = 'Data ou hora em formato inválido.';
} else {
    const diaSemana = dataAlvo.weekday;
    const regraDia = configAgenda.regras_horario[diaSemana];
    if (!regraDia || !Array.isArray(regraDia) || regraDia.length === 0) {
        validacao.motivo = 'A clínica não abre neste dia da semana.';
        validacao.aprovado = false;
    } else {
        const minSol = dataAlvo.hour * 60 + dataAlvo.minute;
        const minFimSol = minSol + DURACAO_MINUTOS;

        let dentroDoExpediente = false;
        for (const periodo of regraDia) {
            if (minSol >= getMin(periodo.ini) && minFimSol <= getMin(periodo.fim)) {
                dentroDoExpediente = true;
                break;
            }
        }

        if (!dentroDoExpediente) {
            validacao.motivo = 'Horário fora do expediente da clínica.';
            validacao.aprovado = false;
        } else {
            const slotInicio = dataAlvo;
            const slotFim = dataAlvo.plus({ minutes: DURACAO_MINUTOS });
            let ocupados = 0;
            for (const evento of eventosOcupados) {
                if (!evento || !evento.start) continue;
                if (evento.status === 'cancelled') continue;
                let iniEvt = DateTime.fromISO(evento.start.dateTime || evento.start.date).setZone(TIMEZONE);
                let fimEvt = DateTime.fromISO(evento.end.dateTime || evento.end.date).setZone(TIMEZONE);
                if (slotInicio < fimEvt && slotFim > iniEvt) ocupados++;
            }
            if (ocupados < CAPACIDADE_MAXIMA) {
                validacao.aprovado = true;
                validacao.motivo = 'Sucesso';
            } else {
                validacao.aprovado = false;
                validacao.motivo = 'Este horário já está ocupado.';
            }
        }
    }
}

return { json: { ...dadosOriginais, validacao } };

